Contents of file .grepo-reference/Grepo_PRD_Package/design/tokens.css:

1 | /* Grepo design contract v1.0. No font files are distributed. */
2 | :root {
3 |   --grepo-canvas: #FAFBF7;
4 |   --grepo-surface: #FFFFFF;
5 |   --grepo-surface-muted: #F3F5F0;
6 |   --grepo-ink: #172019;
7 |   --grepo-text-secondary: #526057;
8 |   --grepo-line: #DFE5DA;
9 |   --grepo-lime: #C6F84A;
10 |   --grepo-lemon: #F2F85B;
11 |   --grepo-green-strong: #28643A;
12 |   --grepo-caution: #7A5200;
13 |   --grepo-error: #A33232;
14 |   --grepo-focus: #365A21;
15 |   --grepo-font-sans: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
16 |   --grepo-font-mono: ui-monospace, "Cascadia Code", "Liberation Mono", monospace;
17 |   --grepo-space-1: 4px; --grepo-space-2: 8px; --grepo-space-3: 12px;
18 |   --grepo-space-4: 16px; --grepo-space-6: 24px; --grepo-space-8: 32px;
19 |   --grepo-radius-control: 12px; --grepo-radius-card: 20px;
20 |   --grepo-shadow-card: 0 6px 24px rgba(23,32,25,.055);
21 |   --grepo-duration-fast: 120ms; --grepo-duration-normal: 180ms;
22 | }
23 | /* Native components must still be tested for contrast, focus and reflow. */
24 | @media (prefers-reduced-motion: reduce) {
25 |   :root { --grepo-duration-fast: 0ms; --grepo-duration-normal: 0ms; }
26 | }
